import { writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
const REPO = join(homedir(), "development", "stallion");
const { chromium, devices } = await import(join(REPO, "node_modules/playwright/index.mjs"));
const { accessHeaders } = await import(join(REPO, "npm-scripts/env.mjs"));
const BASE = "https://stallion.matthijs-f49.workers.dev/";
const DIR = join(homedir(), "development", ".tmp", "stallion-verify");
const ID_RE = /^\/b\/[A-Za-z0-9_-]{12}$/;
const headers = accessHeaders();
if (!headers["CF-Access-Client-Id"]) throw new Error("no access headers");
const browser = await chromium.launch({ headless: true });
const results = [];
for (const scheme of ["light", "dark"]) {
  const r = { scheme, errors: [], ignored: 0, steps: {} };
  const context = await browser.newContext({ ...devices["Galaxy Tab S9"], colorScheme: scheme, extraHTTPHeaders: headers });
  const page = await context.newPage();
  page.on("console", (m) => {
    if (m.type() !== "error") return;
    if (/favicon/i.test(m.text()) || /favicon/i.test(m.location().url ?? "")) { r.ignored++; return; }
    r.errors.push(m.text());
  });
  page.on("pageerror", (e) => r.errors.push(`pageerror ${e.message}`));
  const cdp = await context.newCDPSession(page);
  await cdp.send("Network.enable");
  const ws = [];
  cdp.on("Network.webSocketWillSendHandshakeRequest", (e) => ws.push({ url: e.request.url.replace(/\?.*/, ""), names: Object.keys(e.request.headers).map((h) => h.toLowerCase()) }));
  cdp.on("Network.webSocketHandshakeResponseReceived", (e) => ws.push({ status: e.response.status, reqNames: Object.keys(e.response.requestHeaders ?? {}).map((h) => h.toLowerCase()), cookieHasAuth: /CF_Authorization=/.test(Object.entries(e.response.requestHeaders ?? {}).find(([k]) => k.toLowerCase() === "cookie")?.[1] ?? "") }));
  const shot = async (name) => { const p = join(DIR, `${scheme}-${name}.png`); await page.screenshot({ path: p }); return p; };
  const shots = [];
  await page.goto(BASE, { waitUntil: "load" });
  await page.getByRole("heading", { name: "Stallion" }).waitFor({ timeout: 15000 });
  r.steps.landing = true;
  shots.push(await shot("1-landing"));
  await page.getByRole("button", { name: "New board" }).click();
  await page.waitForURL(/\/b\//);
  const path = new URL(page.url()).pathname;
  r.steps.boardPath = path; r.steps.validId = ID_RE.test(path);
  const boardId = path.slice(3);
  await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });
  await page.locator('.status[data-connection="Connected"]').waitFor({ timeout: 15000 }).then(() => (r.steps.connected = true), () => (r.steps.connected = false));
  r.steps.connection = await page.locator(".status").getAttribute("data-connection");
  r.steps.dotColour = await page.locator(".status").evaluate((el) => getComputedStyle(el).backgroundColor);
  const vp = page.viewportSize();
  const touch = (type, p) => cdp.send("Input.dispatchTouchEvent", { type, touchPoints: p ? [{ x: p.x, y: p.y, id: 1, radiusX: 2, radiusY: 2 }] : [] });
  const pts = Array.from({ length: 24 }, (_, i) => { const t = i / 23; return { x: vp.width / 2 - 150 + t * 300, y: vp.height / 2 + Math.sin(t * Math.PI * 2) * 60 }; });
  await touch("touchStart", pts[0]); for (const p of pts.slice(1)) await touch("touchMove", p); await touch("touchEnd");
  await page.waitForTimeout(3000);
  shots.push(await shot("2-board-drawn"));
  const cookies = await context.cookies();
  r.steps.cfAuthCookie = cookies.some((c) => c.name === "CF_Authorization");
  await page.goBack({ waitUntil: "load" });
  await page.getByRole("heading", { name: "Stallion" }).waitFor({ timeout: 15000 });
  r.steps.backPath = new URL(page.url()).pathname;
  const name = page.getByLabel(`Name for board ${boardId}`);
  r.steps.listed = (await name.count()) === 1;
  const item = page.locator("li.recent", { has: name });
  const thumb = item.locator("img.recent-thumb");
  r.steps.thumbnail = (await thumb.count()) === 1 && (await thumb.evaluate((img) => img.complete && img.naturalWidth > 0 && img.src.startsWith("data:image/png")));
  if (r.steps.thumbnail) {
    r.steps.thumbInk = await thumb.evaluate((img) => { const c = document.createElement("canvas"); c.width = img.naturalWidth; c.height = img.naturalHeight; const x = c.getContext("2d"); x.drawImage(img, 0, 0); const d = x.getImageData(0, 0, c.width, c.height).data; let n = 0; for (let i = 0; i < d.length; i += 4) if (Math.abs(d[i] - d[0]) + Math.abs(d[i+1] - d[1]) + Math.abs(d[i+2] - d[2]) > 48) n++; return Number((n / (d.length / 4)).toFixed(4)); });
  }
  shots.push(await shot("3-landing-listed"));
  const newName = `Verify ${scheme} ${Date.now() % 10000}`;
  await name.fill(newName); await name.press("Enter");
  await page.reload({ waitUntil: "load" });
  await page.getByRole("heading", { name: "Stallion" }).waitFor({ timeout: 15000 });
  r.steps.renamePersisted = (await page.getByLabel(`Name for board ${boardId}`).inputValue()) === newName;
  shots.push(await shot("4-renamed-reloaded"));
  r.ws = ws; r.shots = shots;
  results.push(r);
  await context.close();
}
await browser.close();
console.log(JSON.stringify(results, null, 1));
EOF
